	int age; //年龄

	//嵌套-引用，学生的结构体展示学生
	struct Xuesheng stu;
	//在老师结构体中定义stu变量，可以直接在老师这里修改

};

int main(){
	Laoshi L;//指定Laoshi的变量指定为L
	//定义老师的元素
	L.id = 114514;
	L.name = "老马啊";
	L.age = 45;
	//定义学生的属性
	L.stu.id = 1145369;
	L.stu.name = "小马啊";
	L.stu.age = 12;

	cout << "***" << endl;//输出就不教惹！
}
```
**总结**：在结构体中可以定义另一个结构体作为成员，用来解决实际问题
***
#### 8.5 结构体做函数参数
**作用**：将结构体作为参数向函数中传递
传递方式又两种：
- 值传递
- 地址传递
列示：
```
#include <iostream>
#include <string>

using namespace std;
struct Add{
	//成员列表
	string name;
	int age;
	int score;
};
//1、值传递 - 可以函数更改数据，无法更改实参
void AddCout(struct Add s)
{
	cout << "名字：" << s.name << endl;
	cout << "年龄：" << s.age << endl;
	cout << "分数：" << s.score << endl;
}

//2、地址传递 - 可以更改实参
void AddCout1(struct Add * p)
{
	cout << "名字：" << p->name << endl;
	cout << "年龄：" << p->age << endl;
	cout << "分数：" << p->score << endl;
}

int main(){
	struct Add s;
	s.name = "你好";
	s.age = 18;
	s.score = 100;
	AddCout(s);
	AddCout1(&s);

	return 0;
}
```
**总结**：如果不想改变主函数中的数据，用值传递，反之用地址传递
