#### 4.1.3 成员属性设置为私有
**优点1**：将所有成员属性设置为私有，可以自己控制读写权限
**优点2**：对于写权限，我们可以检测数据的有效性

列示：
``` C++
//成员属性设置私有
#include <iostream>
using namespace std;

class Person {

private: //属性设置为私有
	string m_Nome; //姓名 可读写
	string m_Age; //年龄 只读
	string m_Idol; //偶像 只写

public:
	//设置姓名年龄偶像的函数 - 可在外界类修改
	void setPerson(string name,int age ,string Idol)
	{
		m_Name = name;
		m_Age = age;
		m_Idol = Idol;
	}
	//显示姓名年龄偶像的函数
	void Home()
	{
		cout << name << endl;
		cout << age << endl;
		cout << Idol;
	}
};

int main(){
	string name = "";
	string Iodl = "";
	int age = 0;

	Person s1;
	// s1.m_Name = "张三"; 错误，属性为私有
    // s1.m_Age = 20; 错误，属性为私有
	s1.setPerson(name,age,Iodl);
	s1.Home();
}
```

列示（结构体版本）：
``` C++
//成员属性设置私有
#include <iostream>
using namespace std;

class Person {

private: //属性设置为私有
        struct PersonInfo
    {
        string m_Name;//姓名
        int m_Age;//年龄
        string m_Idol;//偶像
    };
    PersonInfo m_Info;//创建一个PersonInfo结构体对象

public:
//设置姓名年龄偶像的函数
    void setPerson(string name,int age ,string Idol)
    {
        m_Info.m_Name = name;
        m_Info.m_Age = age;
        m_Info.m_Idol = Idol;
    }

//显示姓名年龄偶像的函数
    void Home()
    {
        cout << m_Info.m_Name << endl;
        cout << m_Info.m_Age << endl;
        cout << m_Info.m_Idol << endl;
    }
};

int main(){
    string name = "";
    string Iodl = "";
    int age = 0;
    cin >> name >> age >> Iodl;
    Person s1;
    // s1.m_Name = "张三"; 错误，属性为私有
    // s1.m_Age = 20; 错误，属性为私有
    s1.setPerson(name,age,Iodl);
    s1.Home();

    // s1.PersonInfo As; //错误，PersonInfo结构体为私有
    // As.name = "李四"; //错误，PersonInfo结构体为私有
}
```
封装的应用：
``` C++
#include <iostream>
class Cube {
    int m_H;
    int m_L;
    int m_W;
public:
    Cube(int h, int l, int w) : m_H(h), m_L(l), m_W(w) {}
    int getVolume() {
        return m_H * m_L * m_W;
    }
    int Volume = getVolume();
//体积
    void printVolume() {
        std::cout << "体积: " << Volume << std::endl;
    }
//面积
    void Area() {
        int surfaceArea = m_L * m_W * 2 + m_L * m_H * 2 + m_W * m_H * 2;
        std::cout << "面积: " << surfaceArea << std::endl;
    }
};

void operator!=(const Cube& c1, const Cube& c2) {
    if (c1.Volume != c2.Volume) {
        std::cout << "体积不相等！" << std::endl;
    } else {
        std::cout << "体积相等！" << std::endl;
    }
}

int main() {
    int H, L, W;
    std::cout << "请输入图形一的长、宽、高: " << std::endl;
    std::cin >> H >> L >> W;
    Cube c1(H, L, W);

    int H2, L2, W2;
    std::cout << "请输入图形二的长、宽、高: " << std::endl;
    std::cin >> H2 >> L2 >> W2;
    Cube c2(H2, L2, W2);

    std::cout << "图形一: " << std::endl;
    c1.printVolume(); //C1体积
    c1.Area(); //C1面积

    std::cout << "图形二：" << std::endl;
    c2.printVolume();//C2体积
    c2.Area();//C2面积

    operator!=(c1, c2); //比较C1和C2的体积
    return 0;
}
```
